#include "hash/sha512.h"
#include "hash/sha2_k.h"
#include "util.h"
#include <string.h>

/* the compression function: core/hash/sha512_fast.c (32 bit word pairs, generated by tools/gen_sha512_fast.py) */

void sha512_init(sha512_ctx *c)
{
    SHA2_TABLES();
    for (int i = 0; i < 8; i++) c->h[i] = (uint64_t) sha2_ivh[i] << 32 | sha2_ivl[i];
    c->len = 0;
    c->fill = 0;
}

void sha512_update(sha512_ctx *c, const uint8_t *msg, size_t len)
{
    c->len += len;
    if (c->fill) {
        size_t n = 128 - c->fill;
        if (n > len) n = len;
        memcpy(c->buf + c->fill, msg, n);
        c->fill += (uint32_t)n; msg += n; len -= n;
        if (c->fill < 128) return;
        sha512_block_fast(c->h, c->buf);
        c->fill = 0;
    }
    for (; len >= 128; msg += 128, len -= 128) sha512_block_fast(c->h, msg);
    memcpy(c->buf, msg, len);
    c->fill = (uint32_t)len;
}

void sha512_final(sha512_ctx *c, uint8_t out[64])
{
    uint64_t bits = c->len * 8;
    uint8_t pad[144] = {0x80};
    size_t padlen = (c->fill < 112) ? 112 - c->fill : 240 - c->fill;
    for (int i = 0; i < 8; i++) pad[padlen + 8 + i] = (uint8_t)(bits >> (56 - 8*i)); /* high 64 bits of the 128-bit length stay 0 */
    sha512_update(c, pad, padlen + 16);
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 8; j++) out[8*i + j] = (uint8_t)(c->h[i] >> (56 - 8*j));
}

void sha512(const uint8_t *msg, size_t len, uint8_t out[64])
{
    sha512_ctx c;
    sha512_init(&c);
    sha512_update(&c, msg, len);
    sha512_final(&c, out);
}

void hmac_sha512(const uint8_t *key, size_t klen, const uint8_t *msg, size_t mlen, uint8_t out[64])
{
    uint8_t k[128] = {0}, pad[128], inner[64];
    sha512_ctx c;
    if (klen > 128) sha512(key, klen, k); else memcpy(k, key, klen);
    for (int i = 0; i < 128; i++) pad[i] = k[i] ^ 0x36;
    sha512_init(&c); sha512_update(&c, pad, 128); sha512_update(&c, msg, mlen); sha512_final(&c, inner);
    for (int i = 0; i < 128; i++) pad[i] = k[i] ^ 0x5c;
    sha512_init(&c); sha512_update(&c, pad, 128); sha512_update(&c, inner, 64); sha512_final(&c, out);
    secure_zero(k, sizeof k); secure_zero(pad, sizeof pad); secure_zero(inner, sizeof inner);
}

void pbkdf2_hmac_sha512(const uint8_t *pw, size_t pwlen, const uint8_t *salt, size_t saltlen,
                        uint32_t iterations, uint8_t *out, size_t outlen)
{
    pbkdf2_hmac_sha512_cb(pw, pwlen, salt, saltlen, iterations, out, outlen, NULL, NULL);
}

static uint64_t load_be64(const uint8_t *p)
{
    uint64_t v = 0;
    for (int i = 0; i < 8; i++) v = (v << 8) | p[i];
    return v;
}

int pbkdf2_hmac_sha512_cb(const uint8_t *pw, size_t pwlen, const uint8_t *salt, size_t saltlen,
                          uint32_t iterations, uint8_t *out, size_t outlen, pbkdf2_progress_fn cb, void *user)
{
    int rc = 0;
    /* Precompute the inner/outer HMAC states once; each iteration then only costs 2 compressions, and runs on the state
     * words directly (sha512_hmac64): the output words of one hash are the input words of the next. */
    uint8_t k[128] = {0}, pad[128];
    sha512_ctx ictx, octx, c;
    if (pwlen > 128) sha512(pw, pwlen, k); else memcpy(k, pw, pwlen);
    for (int i = 0; i < 128; i++) pad[i] = k[i] ^ 0x36;
    sha512_init(&ictx); sha512_update(&ictx, pad, 128);
    for (int i = 0; i < 128; i++) pad[i] = k[i] ^ 0x5c;
    sha512_init(&octx); sha512_update(&octx, pad, 128);

    for (uint32_t blk = 1; outlen; blk++) {
        uint8_t ctr[4] = {(uint8_t)(blk >> 24), (uint8_t)(blk >> 16), (uint8_t)(blk >> 8), (uint8_t)blk};
        uint8_t ub[64], tb[64];
        uint64_t u[8], t[8];
        c = ictx; sha512_update(&c, salt, saltlen); sha512_update(&c, ctr, 4); sha512_final(&c, ub);
        c = octx; sha512_update(&c, ub, 64); sha512_final(&c, ub);
        for (int j = 0; j < 8; j++) t[j] = u[j] = load_be64(ub + 8 * j);
        for (uint32_t i = 1; i < iterations; i++) {
            sha512_hmac64(ictx.h, octx.h, u);
            for (int j = 0; j < 8; j++) t[j] ^= u[j];
            if (cb && (i & 1023) == 0 && cb(i, iterations, user)) { rc = -1; break; }
        }
        if (!rc) {
            size_t n = outlen < 64 ? outlen : 64;
            for (int j = 0; j < 64; j++) tb[j] = (uint8_t)(t[j >> 3] >> (56 - 8 * (j & 7)));
            memcpy(out, tb, n);
            out += n; outlen -= n;
        }
        secure_zero(ub, sizeof ub); secure_zero(tb, sizeof tb); secure_zero(u, sizeof u); secure_zero(t, sizeof t);
        if (rc) break;
    }
    secure_zero(k, sizeof k); secure_zero(pad, sizeof pad);
    secure_zero(&ictx, sizeof ictx); secure_zero(&octx, sizeof octx); secure_zero(&c, sizeof c);
    return rc;
}
